package org.example.behavioral_pattern.strategy_pattern.spring_boot;import org.example.behavioral_pattern.strategy_pattern.delivery.EShippingType;import org.example.behavioral_pattern.strategy_pattern.delivery.Order;import org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;@SpringBootApplicationpublic class StrategyApp {    private static ShippingService shippingService;    public StrategyApp(ShippingService shippingService) {        StrategyApp.shippingService = shippingService;    }    public static void main(String[] args) {        SpringApplication.run(StrategyApp.class, args);        Order lightOrder = new Order(800);        Order heavyOrder = new Order(1500);        for (EShippingType type : EShippingType.values()) {            int fee = shippingService.getShippingFee(lightOrder, type);            System.out.println("Light " + type + ": " + fee + "k");        }        for (EShippingType type : EShippingType.values()) {            int fee = shippingService.getShippingFee(heavyOrder, type);            System.out.println("Heavy " + type + ": " + fee + "k");        }    }}// CommandLineRunner trong Spring Boot là một interface đặc biệt cho phép bạn chạy đoạn code ngay sau khi ứng dụng// Spring Boot khởi động xong — tức là sau khi toàn bộ @Bean, @Component, @Service, @Repository đã được khởi tạo và injected đầy đủ.